new={k:j.get('fresh_runs',j.get('runs',0)) for k,j in parts.items()}
result=dict(series='restart R11',major_stage=7,R10_compatible_regression_runs=base['total_fresh_simulation_runs'],retired_R9_native_RETI_RETN_guard_runs=2,new_runs=new,total_fresh_simulation_runs=base['total_fresh_simulation_runs']+sum(new.values()),expected_failure_runs=base['expected_failure_runs'],PC_bits=24,SPS_bits=16,SPL_bits=24,I_bits=16,ADL_reset=0,native_ADL_IM1=True,native_ADL_IM2=True,native_ADL_NMI=True,native_ADL_RETI_RETN=True,ADL_IM0_implemented=False,ADL_IM0_IRQ_gated=True,MADL_and_MBASE_implemented=False,mixed_suffix_frames_implemented=False,P2_COM_unchanged=True,P2_capabilities_diagnostics=0x8287,P2_capabilities_no_diagnostics=0x0287,new_page0_IO=False,original_G80A_unchanged=True,SDRAM_bridge_constraints_unchanged=True,gowin_tested=False,hardware_tested=False,full_MSX_DOS_BIOS_simulated=False,R10_user_report=dict(GOWIN_success=True,LUT_percent=85,EZ80CTL_R10_PASS=True,EZ80ADL_P1_PASS=True,EZ80F9_R9_PASS=True,SofaRun_Space_Manbow_play=True),sha256={str(p.relative_to(r)):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths})
